  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary: Determines whether a customer can book the specified number of seats on the associated trip, considering trip existence, seat availability, overlapping bookings on the same day, and the 2-hour advance booking rule. If eligible, reduces the trip's seat count.
   * Algorithm:
   *   if (customer == null OR trip == null OR bookingDate == null) return false;
   *   if (trip.numberOfSeats < numberOfSeats) return false;
   *   if (this.overlapsWith(trip)) return false;
   *   // Check booking time is more than 2 hours before departure (strictly earlier, not equal)
   *   if (currentTime >= bookingDate + " " + trip.departureTime - 2 hours) return false;
   *   // All checks passed
   *   this.updateTripSeats();
   *   return true;
   * Related Features: Customer (bookings list), Trip (numberOfSeats, departureTime, bookings list), bookingDate, numberOfSeats, overlapsWith, updateTripSeats
   * Related Classes: Customer, Trip
   * Input: Implicitly uses the Booking instance's attributes: customer, trip, bookingDate, numberOfSeats.
   * Output: boolean - true if booking is eligible, false otherwise.
   * Pre-condition: The Booking object exists with its attributes set.
   * Post-condition: If true is returned, the trip's seat inventory is reduced by numberOfSeats. Otherwise, no change.
   * <!-- end-model-doc -->
   * @model kind="operation"
   *        annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public boolean isBookingEligible()
  {
    if (getCustomer() == null || getTrip() == null || getBookingDate() == null) return false;
    if (getTrip().getNumberOfSeats() < getNumberOfSeats()) return false;
    if (overlapsWith(getTrip())) return false;
    
    // Check booking time is more than 2 hours before departure (strictly earlier, not equal)
    // Parse the departureTime from the trip (format "HH:mm")
    String departureTimeStr = getTrip().getDepartureTime();
    if (departureTimeStr == null) return false;
    
    String[] timeParts = departureTimeStr.split(":");
    int departureHour = Integer.parseInt(timeParts[0]);
    int departureMinute = Integer.parseInt(timeParts[1]);
    
    // Build the departure datetime from bookingDate and departureTime
    java.util.Calendar departureCal = java.util.Calendar.getInstance();
    departureCal.setTime(getBookingDate());
    departureCal.set(java.util.Calendar.HOUR_OF_DAY, departureHour);
    departureCal.set(java.util.Calendar.MINUTE, departureMinute);
    departureCal.set(java.util.Calendar.SECOND, 0);
    departureCal.set(java.util.Calendar.MILLISECOND, 0);
    
    // Subtract 2 hours
    departureCal.add(java.util.Calendar.HOUR_OF_DAY, -2);
    
    // Get current time
    java.util.Date currentTime = new java.util.Date();
    
    // If current time is >= (bookingDate + departureTime - 2 hours), booking is not eligible
    if (!currentTime.before(departureCal.getTime())) return false;
    
    // All checks passed
    updateTripSeats();
    return true;
  }

